/** @typedef {{ enabled: boolean, id: string, options: { attempts: number, tags: string[] } }} Provider */

/** @type {Map<string, unknown>} */
const providers = new Map();

/** @param {string} message @returns {never} */
function fail(message) {
  throw new Error(message);
}

/** @param {string} id @param {Provider} provider */
export function registerProvider(id, provider) {
  providers.set(id, provider);
}

/** @param {string} id @returns {Provider | undefined} */
export function lookupProvider(id) {
  const provider = providers.get(id);
  if (provider === undefined) return undefined;
  return /** @type {Provider} */ (provider);
}

/** @param {string} id @returns {Provider} */
export function requiredProvider(id) {
  return lookupProvider(id) ?? fail(`missing:${id}`);
}

/** @param {string} id @returns {boolean} */
export function hasProvider(id) {
  return providers.has(id);
}
